output_text:
[
  {
    "id": "return_cart_to_register",
    "text": "Anyone who takes a shopping cart is obliged to return it to the register-side cart return at cell (0,1) before leaving.",
    "abstraction": {
      "state_properties": {
        "at_register_cart_return": "at(0,1)",
        "cart_parked_at_register": "cartAt(0,1)"
      },
      "events": {
        "take_cart": {
          "pre": "PICKUP_CART",
          "post": "hasCart"
        },
        "return_cart_to_register": {
          "pre": {
            "and": [
              "LEAVE_CART",
              "at_register_cart_return"
            ]
          },
          "post": "cart_parked_at_register"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "take_cart",
      "discharge": "return_cart_to_register"
    }
  },
  {
    "id": "no_exit_until_cart_returned",
    "text": "It is forbidden to exit the supermarket unless the cart has already been parked at the register-side cart return.",
    "abstraction": {
      "state_properties": {
        "cart_parked_at_register": "cartAt(0,1)"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "EXIT",
          {
            "not": "cart_parked_at_register"
          }
        ]
      }
    }
  },
  {
    "id": "no_cart_on_exit_highway",
    "text": "Customers may not push a cart along the bottom exit aisle, which explains why the cart is left behind before walking to the exit.",
    "abstraction": {
      "state_properties": {
        "bottom_exit_aisle": {
          "or": [
            "at(0,5)",
            "at(1,5)",
            "at(2,5)",
            "at(3,5)",
            "at(4,5)",
            "at(5,5)",
            "at(6,5)",
            "at(7,5)",
            "at(8,5)",
            "at(9,5)"
          ]
        },
        "pushing_cart": "hasCart"
      },
      "events": {
        "cart_lateral_travel_on_exit_aisle": {
          "pre": {
            "and": [
              "pushing_cart",
              "bottom_exit_aisle",
              {
                "or": [
                  "E",
                  "W",
                  "EXIT"
                ]
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cart_lateral_travel_on_exit_aisle"
    }
  },
  {
    "id": "must_drop_cart_at_register",
    "text": "Upon reaching the register-side cart return while pushing a cart, the customer is obliged to put the cart down there.",
    "abstraction": {
      "state_properties": {
        "at_register_cart_return": "at(0,1)",
        "pushing_cart": "hasCart"
      },
      "events": {
        "arrive_at_register_with_cart": {
          "pre": {
            "and": [
              "pushing_cart",
              "at_register_cart_return"
            ]
          },
          "post": null
        },
        "drop_cart_at_register": {
          "pre": {
            "and": [
              "LEAVE_CART",
              "at_register_cart_return"
            ]
          },
          "post": "cartAt(0,1)"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "arrive_at_register_with_cart",
      "discharge": "drop_cart_at_register"
    }
  },
  {
    "id": "cart_only_parking_zone",
    "text": "It is forbidden to leave a shopping cart anywhere except the designated register-side cart return.",
    "abstraction": {
      "state_properties": {
        "designated_cart_return": "at(0,1)"
      },
      "events": {
        "abandon_cart_outside_return": {
          "pre": {
            "and": [
              "LEAVE_CART",
              {
                "not": "designated_cart_return"
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "abandon_cart_outside_return"
    }
  },
  {
    "id": "items_must_go_in_cart",
    "text": "Shelf items must be picked up only while the customer has a cart, rather than being carried by hand.",
    "abstraction": {
      "state_properties": {
        "has_shopping_cart": "hasCart",
        "carrying_item_by_hand": "handFull"
      },
      "events": {
        "take_shelf_item_without_cart": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              {
                "not": "has_shopping_cart"
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "take_shelf_item_without_cart"
    }
  },
  {
    "id": "no_hand_carrying_in_store",
    "text": "Customers are prohibited from walking through the store while carrying groceries by hand.",
    "abstraction": {
      "state_properties": {
        "hands_occupied": "handFull"
      },
      "events": {
        "walk_with_item_in_hand": {
          "pre": {
            "and": [
              "MOVE",
              "hands_occupied"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "walk_with_item_in_hand"
    }
  },
  {
    "id": "take_entrance_cart_before_shopping",
    "text": "Before collecting any required shelf item, a customer is obliged to take the entrance cart stationed at cell (1,5).",
    "abstraction": {
      "state_properties": {
        "at_entrance_cart_station": "at(1,5)",
        "entrance_cart_available": "cartAt(1,5)",
        "has_shopping_cart": "hasCart"
      },
      "events": {
        "take_entrance_cart": {
          "pre": {
            "and": [
              "PICKUP_CART",
              "at_entrance_cart_station",
              "entrance_cart_available"
            ]
          },
          "post": "has_shopping_cart"
        },
        "collect_shelf_item": {
          "pre": "PICKUP_ITEM",
          "post": null
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "take_entrance_cart"
    }
  }
]
